public class InnerCapacityProviderLaunchParametersFactory(Action<Humidifier.BedrockAgentCore.CapacityProviderTypes.LaunchParameters> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.CapacityProviderTypes.LaunchParameters>
{

    internal InnerCapacityProviderInstanceRequirementsFactory InstanceRequirementsFactory { get; set; }

    internal InnerCapacityProviderCapacityReservationSpecificationFactory CapacityReservationSpecificationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.CapacityProviderTypes.LaunchParameters Create()
    {
        var launchParametersResult = CreateLaunchParameters();
        factoryAction?.Invoke(launchParametersResult);

        return launchParametersResult;
    }

    private Humidifier.BedrockAgentCore.CapacityProviderTypes.LaunchParameters CreateLaunchParameters()
    {
        var launchParametersResult = new Humidifier.BedrockAgentCore.CapacityProviderTypes.LaunchParameters();

        return launchParametersResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.CapacityProviderTypes.LaunchParameters result)
    {
        base.CreateChildren(result);

        result.InstanceRequirements ??= InstanceRequirementsFactory?.Build();
        result.CapacityReservationSpecification ??= CapacityReservationSpecificationFactory?.Build();
    }

} // End Of Class

